@{66a98ef5bf4acafa8f98e7db|full_name} Here is a very simple way to sort playerApis using bubble sort :D

```

private VRCPlayerApi[] GetSortedVRCPlayerAPIs()

{

    var players = new VRCPlayerApi[VRCPlayerApi.GetPlayerCount()];  

    VRCPlayerApi.GetPlayers(players);



    bool hasSwapped;

    do {

        hasSwapped = false;

        for (int i = 0; i < players.Length - 1; i++) {

            if (players[i].playerId < players[i + 1].playerId) {

                var temp = players[i];

                players[i] = players[i + 1];

                players[i + 1] = temp;

                hasSwapped = true;

            }

        }

    } while (hasSwapped);



    return players;

}

```

Edit: I still would not recommend doing things like this, as you should really just use the playerID.
